def decrypt_byte(c, kb, n, key_len, j):
    # Reverse of encrypt: c = (m + k) mod 2^n
    # But the key byte kb is the full byte; we need the nibble/byte at position j
    # The key is repeated, so key byte at j is key[j % key_len]
    # In encrypt, the key byte is split into n-bit chunks
    # So we need to recover the full key byte from the nibble
    # m = (c - k) mod 2^n
    m = (c - kb) & ((1 << n) - 1)
    return m


